1	package com.example.starter.ride;
2	
3	import java.time.Clock;
4	import java.time.LocalDate;
5	import java.util.Arrays;
6	import java.util.LinkedHashMap;
7	import java.util.List;
8	import java.util.Map;
9	
10	import org.springframework.stereotype.Service;
11	import org.springframework.transaction.annotation.Transactional;
12	
13	import com.example.starter.ride.Idempotency.ApiResult;
14	import com.example.starter.ride.dto.RideDtos.ArchiveRequest;
15	import com.example.starter.ride.dto.RideDtos.CheckItem;
16	import com.example.starter.ride.dto.RideDtos.CreateRideRequest;
17	import com.example.starter.ride.dto.RideDtos.DailyCheckRequest;
18	import com.example.starter.ride.dto.RideDtos.OpenRequest;
19	import com.example.starter.ride.dto.RideDtos.ReadingRequest;
20	import com.example.starter.ride.dto.RideDtos.RecheckRequest;
21	import com.example.starter.ride.dto.RideDtos.ReopenRequest;
22	import com.example.starter.ride.dto.RideDtos.SafetyFaultRequest;
23	import com.example.starter.ride.dto.RideDtos.TrialRunRequest;
24	import com.fasterxml.jackson.databind.ObjectMapper;
25	
26	/**
27	 * 游乐设施日检与载客联锁核心服务。
28	 * 状态链：日检→试运行(恰3次)→开放→运行监测→闭园归档；
29	 * 故障停运/缓停→复检合格→复开(同日恰2次合法)。
30	 * 所有状态流转在事务内持行锁串行执行，保证同一设备同时刻只有一条状态链。
31	 */
32	@Service
33	public class RideService {
34	
35	    private final RideRepository rides;
36	    private final RideRecordRepository records;
37	    private final Idempotency.Executor idempotency;
38	    private final ObjectMapper objectMapper;
39	    private final Clock clock;
40	
41	    public RideService(RideRepository rides, RideRecordRepository records,
42	            Idempotency.Executor idempotency, ObjectMapper objectMapper, Clock clock) {
43	        this.rides = rides;
44	        this.records = records;
45	        this.idempotency = idempotency;
46	        this.objectMapper = objectMapper;
47	        this.clock = clock;
48	    }
49	
50	    /** 创建设备（合成数据），初始状态为待日检。 */
51	    @Transactional
52	    public Map<String, Object> createRide(CreateRideRequest request) {
53	        Ride ride = rides.insert(request.name(), request.maxLoad(), request.maxSpeed());
54	        records.insertEvent(ride.id(), "CREATE", "设备登记：" + ride.name());
55	        return rideView(ride);
56	    }
57	
58	    /** 日检：清单逐项合格方可试运行；安全装置任一失效整机立即停运。 */
59	    public ApiResult dailyCheck(long rideId, DailyCheckRequest request) {
60	        return idempotency.execute(request.requestId(), "DAILY_CHECK", rideId, request, () -> {
61	            Ride ride = lock(rideId);
62	            requireStatus(ride, "当前状态不允许日检",
63	                    RideStatus.PENDING_CHECK, RideStatus.CHECKED);
64	            boolean allPassed = request.items().stream().allMatch(CheckItem::passed);
65	            List<String> failedSafety = request.items().stream()
66	                    .filter(item -> !item.passed() && isSafetyDevice(item.itemName()))
67	                    .map(CheckItem::itemName)
68	                    .toList();
69	            LocalDate today = LocalDate.now(clock);
70	            records.insertDailyCheck(rideId, request.requestId(), today, allPassed, request.items());
71	            records.insertEvent(rideId, "DAILY_CHECK",
72	                    allPassed ? "日检清单逐项合格" : "日检存在不合格项");
73	
74	            RideStatus newStatus = ride.status();
75	            LocalDate checkDate = ride.checkDate();
76	            int trialCount = ride.trialCount();
77	            if (allPassed) {
78	                newStatus = RideStatus.CHECKED;
79	                checkDate = today;
80	                trialCount = 0;
81	            } else if (!failedSafety.isEmpty()) {
82	                newStatus = RideStatus.STOPPED;
83	                records.insertEvent(rideId, "FAULT_STOP",
84	                        "安全装置失效立即停运：" + String.join("、", failedSafety));
85	            }
86	            update(ride, newStatus, trialCount, ride.reopenCount(), checkDate, ride.reopenDate());
87	
88	            Map<String, Object> body = rideView(rideId);
89	            body.put("allPassed", allPassed);
90	            body.put("checkDate", allPassed ? today.toString() : null);
91	            return ok(body);
92	        });
93	    }
94	
95	    /** 试运行：恰3次空载无异常方可载客；任一次异常立即故障停运。 */
96	    public ApiResult trialRun(long rideId, TrialRunRequest request) {
97	        return idempotency.execute(request.requestId(), "TRIAL_RUN", rideId, request, () -> {
98	            Ride ride = lock(rideId);
99	            requireStatus(ride, "日检合格后方可试运行", RideStatus.CHECKED);
100	            int seq = ride.trialCount() + 1;
101	            records.insertTrialRun(rideId, request.requestId(), seq, request.normal());
102	
103	            RideStatus newStatus = RideStatus.CHECKED;
104	            int trialCount = ride.trialCount();
105	            if (request.normal()) {
106	                trialCount = seq;
107	                records.insertEvent(rideId, "TRIAL_RUN", "第" + seq + "次空载试运行正常");
108	                if (trialCount == Ride.REQUIRED_TRIAL_COUNT) {
109	                    newStatus = RideStatus.READY;
110	                    records.insertEvent(rideId, "TRIAL_RUN", "试运行恰3次合格，允许开放载客");
111	                }
112	            } else {
113	                newStatus = RideStatus.STOPPED;
114	                trialCount = 0;
115	                records.insertEvent(rideId, "FAULT_STOP", "第" + seq + "次试运行异常，整机立即停运");
116	            }
117	            update(ride, newStatus, trialCount, ride.reopenCount(),
118	                    ride.checkDate(), ride.reopenDate());
119	            return ok(rideView(rideId));
120	        });
121	    }
122	
123	    /** 开放：须当日日检合格且试运行恰3次合格；未日检设备无法开放；并发开放唯一成功。 */
124	    public ApiResult open(long rideId, OpenRequest request) {
125	        return idempotency.execute(request.requestId(), "OPEN", rideId, request, () -> {
126	            Ride ride = lock(rideId);
127	            if (ride.checkDate() == null || !ride.checkDate().equals(LocalDate.now(clock))) {
128	                throw ApiException.conflict("未日检设备无法开放");
129	            }
130	            requireStatus(ride, "当前状态不允许开放，须试运行恰3次合格",
131	                    RideStatus.READY);
132	            update(ride, RideStatus.OPEN, ride.trialCount(), ride.reopenCount(),
133	                    ride.checkDate(), ride.reopenDate());
134	            records.insertEvent(rideId, "OPEN", "设备开放载客");
135	            return ok(rideView(rideId));
136	        });
137	    }
138	
139	    /** 安全装置失效上报：压杠、安全带与联锁装置任一失效整机立即停运。 */
140	    public ApiResult safetyFault(long rideId, SafetyFaultRequest request) {
141	        return idempotency.execute(request.requestId(), "SAFETY_FAULT", rideId, request, () -> {
142	            if (!isSafetyDevice(request.device())) {
143	                throw ApiException.unprocessable("未知安全装置：" + request.device()
144	                        + "，合法值为压杠/安全带/联锁装置");
145	            }
146	            Ride ride = lock(rideId);
147	            if (ride.status() == RideStatus.ARCHIVED) {
148	                throw ApiException.conflict("设备已归档，拒绝安全装置失效上报");
149	            }
150	            if (ride.status() == RideStatus.STOPPED) {
151	                Map<String, Object> body = rideView(rideId);
152	                body.put("message", "设备已处于故障停运状态");
153	                return ok(body);
154	            }
155	            requireStatus(ride, "设备未在运行流程中，无法上报安全装置失效",
156	                    RideStatus.CHECKED, RideStatus.READY, RideStatus.OPEN,
157	                    RideStatus.SUSPENDED, RideStatus.RECHECKED);
158	            update(ride, RideStatus.STOPPED, ride.trialCount(), ride.reopenCount(),
159	                    ride.checkDate(), ride.reopenDate());
160	            records.insertEvent(rideId, "FAULT_STOP",
161	                    "安全装置失效立即停运：" + request.device());
162	            return ok(rideView(rideId));
163	        });
164	    }
165	
166	    /** 复检：故障停运或缓停后复检合格方可复开。 */
167	    public ApiResult recheck(long rideId, RecheckRequest request) {
168	        return idempotency.execute(request.requestId(), "RECHECK", rideId, request, () -> {
169	            Ride ride = lock(rideId);
170	            requireStatus(ride, "仅故障停运或缓停设备可复检",
171	                    RideStatus.STOPPED, RideStatus.SUSPENDED);
172	            boolean allPassed = request.items().stream().allMatch(CheckItem::passed);
173	            if (allPassed) {
174	                update(ride, RideStatus.RECHECKED, ride.trialCount(), ride.reopenCount(),
175	                        ride.checkDate(), ride.reopenDate());
176	                records.insertEvent(rideId, "RECHECK", "复检合格，允许复开");
177	            } else {
178	                List<String> failed = request.items().stream()
179	                        .filter(item -> !item.passed())
180	                        .map(CheckItem::itemName)
181	                        .toList();
182	                records.insertEvent(rideId, "RECHECK",
183	                        "复检不合格：" + String.join("、", failed));
184	            }
185	            Map<String, Object> body = rideView(rideId);
186	            body.put("allPassed", allPassed);
187	            return ok(body);
188	        });
189	    }
190	
191	    /** 复开：同日复开最多2次，恰2次合法，超出当日禁开。 */
192	    public ApiResult reopen(long rideId, ReopenRequest request) {
193	        return idempotency.execute(request.requestId(), "REOPEN", rideId, request, () -> {
194	            Ride ride = lock(rideId);
195	            requireStatus(ride, "仅复检合格设备可复开", RideStatus.RECHECKED);
196	            LocalDate today = LocalDate.now(clock);
197	            int used = today.equals(ride.reopenDate()) ? ride.reopenCount() : 0;
198	            if (used >= Ride.MAX_DAILY_REOPEN) {
199	                throw ApiException.unprocessable(
200	                        "同日复开已达上限" + Ride.MAX_DAILY_REOPEN + "次，当日禁开");
201	            }
202	            int reopenCount = used + 1;
203	            update(ride, RideStatus.OPEN, ride.trialCount(), reopenCount,
204	                    ride.checkDate(), today);
205	            records.insertEvent(rideId, "REOPEN", "当日第" + reopenCount + "次复开");
206	            return ok(rideView(rideId));
207	        });
208	    }
209	
210	    /** 闭园归档：终态；重复归档返回幂等成功；归档后迟到运行数据只记迟到事件。 */
211	    public ApiResult archive(long rideId, ArchiveRequest request) {
212	        return idempotency.execute(request.requestId(), "ARCHIVE", rideId, request, () -> {
213	            Ride ride = lock(rideId);
214	            if (ride.status() == RideStatus.ARCHIVED) {
215	                Map<String, Object> body = rideView(rideId);
216	                body.put("message", "设备已归档，重复归档幂等成功");
217	                return ok(body);
218	            }
219	            update(ride, RideStatus.ARCHIVED, ride.trialCount(), ride.reopenCount(),
220	                    ride.checkDate(), ride.reopenDate());
221	            records.insertEvent(rideId, "ARCHIVE", "闭园归档，进入终态");
222	            return ok(rideView(rideId));
223	        });
224	    }
225	
226	    /**
227	     * 运行监测读数：载荷或速度超阈值触发缓停，恰等阈值合格；
228	     * 归档后迟到数据只记迟到事件，不改变状态。
229	     */
230	    @Transactional
231	    public Map<String, Object> reading(long rideId, ReadingRequest request) {
232	        Ride ride = lock(rideId);
233	        if (ride.status() == RideStatus.ARCHIVED) {
234	            records.insertReading(rideId, request.loadValue(), request.speedValue(), false, true);
235	            records.insertEvent(rideId, "LATE_READING",
236	                    "归档后迟到运行数据：载荷=" + request.loadValue()
237	                            + "，速度=" + request.speedValue());
238	            Map<String, Object> body = rideView(ride);
239	            body.put("late", true);
240	            body.put("message", "设备已归档，迟到数据仅记录事件");
241	            return body;
242	        }
243	        if (ride.status() != RideStatus.OPEN) {
244	            throw ApiException.conflict("设备未开放，拒绝运行监测读数");
245	        }
246	        boolean exceeded = request.loadValue() > ride.maxLoad()
247	                || request.speedValue() > ride.maxSpeed();
248	        records.insertReading(rideId, request.loadValue(), request.speedValue(), exceeded, false);
249	        if (exceeded) {
250	            update(ride, RideStatus.SUSPENDED, ride.trialCount(), ride.reopenCount(),
251	                    ride.checkDate(), ride.reopenDate());
252	            records.insertEvent(rideId, "SLOW_STOP",
253	                    "载荷或速度超阈值触发缓停：载荷=" + request.loadValue()
254	                            + "/" + ride.maxLoad() + "，速度=" + request.speedValue()
255	                            + "/" + ride.maxSpeed());
256	        } else {
257	            records.insertEvent(rideId, "READING",
258	                    "运行读数合格：载荷=" + request.loadValue()
259	                            + "，速度=" + request.speedValue());
260	        }
261	        Map<String, Object> body = rideView(rideId);
262	        body.put("exceeded", exceeded);
263	        return body;
264	    }
265	
266	    /** 查询设备当前状态。 */
267	    @Transactional(readOnly = true)
268	    public Map<String, Object> getRide(long rideId) {
269	        return rideView(rides.findById(rideId)
270	                .orElseThrow(() -> ApiException.notFound("设备不存在：" + rideId)));
271	    }
272	
273	    /** 启停链事件，可复算。 */
274	    @Transactional(readOnly = true)
275	    public List<Map<String, Object>> listEvents(long rideId) {
276	        ensureExists(rideId);
277	        return records.listEvents(rideId);
278	    }
279	
280	    /** 日检清单（含明细），可复算。 */
281	    @Transactional(readOnly = true)
282	    public List<Map<String, Object>> listDailyChecks(long rideId) {
283	        ensureExists(rideId);
284	        List<Map<String, Object>> checks = records.listDailyChecks(rideId);
285	        for (Map<String, Object> check : checks) {
286	            long checkId = ((Number) check.get("id")).longValue();
287	            check.put("items", records.listDailyCheckItems(checkId));
288	        }
289	        return checks;
290	    }
291	
292	    /** 试运行记录，可复算。 */
293	    @Transactional(readOnly = true)
294	    public List<Map<String, Object>> listTrialRuns(long rideId) {
295	        ensureExists(rideId);
296	        return records.listTrialRuns(rideId);
297	    }
298	
299	    /** 运行读数记录。 */
300	    @Transactional(readOnly = true)
301	    public List<Map<String, Object>> listReadings(long rideId) {
302	        ensureExists(rideId);
303	        return records.listReadings(rideId);
304	    }
305	
306	    private void ensureExists(long rideId) {
307	        if (rides.findById(rideId).isEmpty()) {
308	            throw ApiException.notFound("设备不存在：" + rideId);
309	        }
310	    }
311	
312	    private Ride lock(long rideId) {
313	        return rides.findByIdForUpdate(rideId)
314	                .orElseThrow(() -> ApiException.notFound("设备不存在：" + rideId));
315	    }
316	
317	    private void requireStatus(Ride ride, String message, RideStatus... allowed) {
318	        if (Arrays.stream(allowed).noneMatch(s -> s == ride.status())) {
319	            throw ApiException.conflict(message + "（当前状态：" + ride.status() + "）");
320	        }
321	    }
322	
323	    private void update(Ride ride, RideStatus status, int trialCount, int reopenCount,
324	            LocalDate checkDate, LocalDate reopenDate) {
325	        if (!rides.updateWithVersion(ride, status, trialCount, reopenCount,
326	                checkDate, reopenDate)) {
327	            throw ApiException.conflict("设备状态并发变更，请重试");
328	        }
329	    }
330	
331	    private boolean isSafetyDevice(String name) {
332	        return Arrays.asList(Ride.SAFETY_DEVICES).contains(name);
333	    }
334	
335	    private Map<String, Object> rideView(long rideId) {
336	        return rideView(rides.findById(rideId).orElseThrow());
337	    }
338	
339	    private Map<String, Object> rideView(Ride ride) {
340	        Map<String, Object> view = new LinkedHashMap<>();
341	        view.put("rideId", ride.id());
342	        view.put("name", ride.name());
343	        view.put("status", ride.status().name());
344	        view.put("maxLoad", ride.maxLoad());
345	        view.put("maxSpeed", ride.maxSpeed());
346	        view.put("trialCount", ride.trialCount());
347	        view.put("reopenCount", ride.reopenCount());
348	        view.put("checkDate", ride.checkDate() == null ? null : ride.checkDate().toString());
349	        return view;
350	    }
351	
352	    private ApiResult ok(Map<String, Object> body) {
353	        try {
354	            return new ApiResult(200, objectMapper.writeValueAsString(body));
355	        } catch (com.fasterxml.jackson.core.JsonProcessingException e) {
356	            throw new IllegalStateException("响应序列化失败", e);
357	        }
358	    }
359	}
