290	        assertEquals(200, again.status());
291	        assertEquals("ARCHIVED", bodyOf(again).get("status"));
292	
293	        // 迟到运行数据只记迟到事件，状态不变
294	        Map<String, Object> late = service.reading(rideId, new ReadingRequest(99, 99));
295	        assertTrue((Boolean) late.get("late"));
296	        assertEquals("ARCHIVED", statusOf(rideId));
297	        List<Map<String, Object>> events = service.listEvents(rideId);
298	        assertTrue(events.stream().anyMatch(ev -> "LATE_READING".equals(ev.get("event_type"))));
299	        List<Map<String, Object>> readings = service.listReadings(rideId);
300	        assertEquals(1, readings.size());
301	        assertTrue((Boolean) readings.get(0).get("late"));
302	
303	        // 归档后禁止开放、日检、停运
304	        assertThrows(ApiException.class,
305	                () -> service.open(rideId, new OpenRequest("k-open-2")));
306	        assertThrows(ApiException.class,
