314	    @DisplayName("缓停后复检合格可复开，计入同日复开次数")
315	    void suspendedRideReopensAfterRecheck() {
316	        makeOpen(rideId, "k");
317	        service.reading(rideId, new ReadingRequest(11, 50));
318	        assertEquals("SUSPENDED", statusOf(rideId));
319	        service.recheck(rideId, new RecheckRequest("k-r1",
320	                List.of(new CheckItem("制动系统", true))));
321	        ApiResult reopened = service.reopen(rideId, new ReopenRequest("k-re1"));
322	        assertEquals("OPEN", bodyOf(reopened).get("status"));
323	        assertEquals(1, bodyOf(reopened).get("reopenCount"));
324	    }
325	
326	    @Test
327	    @DisplayName("启停链事件完整可复算")
328	    void eventChainIsRecomputable() {
329	        makeOpen(rideId, "k");
330	        service.safetyFault(rideId, new SafetyFaultRequest("k-f1", "压杠"));
331	        service.recheck(rideId, new RecheckRequest("k-r1",
332	                List.of(new CheckItem("压杠", true))));
333	        service.reopen(rideId, new ReopenRequest("k-re1"));
334	        service.archive(rideId, new ArchiveRequest("k-arch"));
335	
336	        List<String> types = service.listEvents(rideId).stream()
337	                .map(ev -> (String) ev.get("event_type"))
338	                .toList();
339	        assertEquals(List.of("CREATE", "DAILY_CHECK", "TRIAL_RUN", "TRIAL_RUN", "TRIAL_RUN",
340	                "TRIAL_RUN", "OPEN", "FAULT_STOP", "RECHECK", "REOPEN", "ARCHIVE"), types);
341	    }
342	}
