        update(ride, RideStatus.OPEN, ride.trialCount(), ride.reopenCount(),
                ride.checkDate(), ride.reopenDate());
        records.insertEvent(rideId, "OPEN", "设备开放载客");
        return ok(rideView(rideId));
    });
}

