/** 撤销证书：撤销当前证书后开放资格立即失效；重复撤销幂等成功。 */
public ApiResult revokeCertificate(long rideId, long certificateId, RevokeCertificateRequest request) {
    return idempotency.execute(request.requestId(), "CERT_REVOKE", rideId, request, () -> {
