/** 大修后监督检验确认：两名不同检验人共同确认全清单合格，绑定当前大修版本。 */
public ApiResult confirmOverhaulInspection(long rideId, OverhaulInspectionRequest request) {
    return idempotency.execute(request.requestId(), "OVERHAUL_INSPECTION", rideId, request, () -> {
        Ride ride = lock(rideId);
        requireVersion(ride, request.expectedVersion());
        requireInspected(ride);
        if (ride.status() == RideStatus.ARCHIVED) throw unprocessable("设备已归档");
        if (ride.overhaulVersion() == 0) throw unprocessable("设备未登记大修，无需监督检验");
        if (request.inspectorOne().equals(request.inspectorTwo())) throw unprocessable("两名检验人须为不同人员");
        boolean allPassed = request.items().stream().allMatch(CheckItem::passed);
        long inspectionId = certificates.insertOverhaulInspection(rideId, request.requestId(), ride.overhaulVersion(), request.inspectorOne(), request.inspectorTwo(), allPassed, request.items());
        records.insertEvent(rideId, "OVERHAUL_INSPECTION", allPassed ? "监督检验双人确认全清单合格，恢复开放资格（不自动开放）" : "监督检验存在不合格项");
        // 确认后只恢复开放资格：不改变状态、不重置当日复开次数；版本+1
        update(ride, ride.status(), ride.trialCount(), ride.reopenCount(), ride.checkDate(), ride.reopenDate(), ride.overhaulVersion(), ride.currentCertificateId());
        Map<String, Object> body = rideView(rideId);
        body.put("allPassed", allPassed);
        body.put("overhaulVersion", ride.overhaulVersion());
        return ok(body);
    });
}
