                .andExpect(jsonPath("$[0].overhaul_version").value(1))
                .andExpect(jsonPath("$[0].items[0].item_name").value("主体结构"));
    }

    @Test
    @DisplayName("REST 错误语义：缺参400、设备不存在404、无证书开放422、版本冲突409")
